def _review_entry(identity, relation_set, declared, subjects, role):
    context = CONTEXTS[identity[0]]
    updates = {'subjects': subjects, 'control_field_binding_complete': True,
               'unresolved_glyphs': [], 'operand_binding_required': bool(subjects),
               'source_formulas': [], 'ranges': [], 'comparisons': [], 'numeric_values': [],
               'source_relation_group': 'AB_network_%s_%s' % (identity[2], identity[3])}
    review = {'rules': RULESETS[relation_set], 'full_clause_review': True,
              'value_updates': updates, 'additional_pages': context['pages']}
    if relation_set == 'c7bd63484a5b':
        review['additional_sources'] = [{'manual_id': 'fx5_communication_j',
            'manual_number': 'SH-082625ENG', 'revision': 'J', 'pdf_pages': [865]}]
    if role:
        review['content_role'] = role
    if role == 'source_conflict':
        review['status'] = 'conflict'
        updates.update(gap_kind='source_conflict', source_disposition='source_conflict')
    return {'context_sha256': context['sha256'], 'declared': declared, 'review': review}


REVIEWS = {identity: _review_entry(identity, relation_set, declared, subjects, role)
           for identity, relation_set, declared, subjects, role in SOURCES}


def review_network_backlog_clause(kind, clause, *, section, block, value, declared):
    key = (section.get('section_token'), kind, block.get('page'), block.get('line'),
           hashlib.sha256(clause.encode()).hexdigest())
    entry = REVIEWS.get(key)
    if entry is None:
        return None
    context = json.dumps({k: section.get(k) for k in
        ('outline', 'text', 'page_layouts', 'page_texts', 'first_page')},
        ensure_ascii=False, separators=(',', ':'))
    if hashlib.sha256(context.encode()).hexdigest() != entry['context_sha256']:
        return None
    # The complete source declaration is part of the review scope. Do not
    # silently project a multi-form/overload review into a different signature.
    if not (set(entry['declared']) - {'en', 'eno'}) <= set(declared):
        return None
    return deepcopy(entry['review'])
